using System;
namespace ImeSharp {internal static class InputMethod {public static bool Enabled {get=>Engine.UnityRuntime.Host.ImeEnabled;set=>Engine.UnityRuntime.Host.ImeEnabled=value;} public static bool ShowOSImeWindow=true;public static string[] CandidateList=Array.Empty<string>();public static int CandidateSelection=0,CandidatePageSize=0;public static event Action<string,int> TextCompositionCallback{add=>Engine.UnityRuntime.Host.ImeComposition+=value;remove=>Engine.UnityRuntime.Host.ImeComposition-=value;}public static event Action<char> TextInputCallback{add=>Engine.UnityRuntime.Host.ImeText+=value;remove=>Engine.UnityRuntime.Host.ImeText-=value;}public static void Initialize(IntPtr handle){Engine.UnityRuntime.Host.WindowHandle=handle;}public static void SetTextInputRect(int x,int y,int w,int h){Engine.UnityRuntime.Host.ImePosition=new Engine.Point2(x,y);}}}
namespace System.Threading {public sealed class Lock {readonly object gate=new object();public void Enter()=>Monitor.Enter(gate);public void Exit()=>Monitor.Exit(gate);public bool IsHeldByCurrentThread=>Monitor.IsEntered(gate);public bool TryEnter()=>Monitor.TryEnter(gate);public bool TryEnter(int millisecondsTimeout)=>Monitor.TryEnter(gate,millisecondsTimeout);public bool TryEnter(TimeSpan timeout)=>Monitor.TryEnter(gate,timeout);public Scope EnterScope(){Enter();return new Scope(this);}public readonly ref struct Scope{readonly Lock owner;internal Scope(Lock value){owner=value;}public void Dispose()=>owner.Exit();}}}
